<?php
require_once __DIR__ . '/Model.php';
class AttendanceModel extends Model { protected $table = 'attendance'; public function register($student, $date, $status, $reason, $obs, $by) { try { db()->prepare('CALL sp_register_attendance(?,?,?,?,?,?)')->execute([(int)$student, $date, $status, $reason, $obs, (int)$by]); return true; } catch (Throwable $e) { $sql = 'INSERT INTO attendance (student_id, attendance_date, status, reason, observation, registered_by) VALUES (?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status), reason=VALUES(reason), observation=VALUES(observation)'; db()->prepare($sql)->execute([(int)$student, $date, $status, $reason, $obs, (int)$by]); if (in_array($status, ['F', 'R', 'L', 'RC'])) { db()->prepare('INSERT INTO notifications (user_id,title,message,type,created_at) SELECT us.user_id, "Registro de asistencia", CONCAT("El/La estudiante registra: ",?," el ",?,". Motivo: ",COALESCE(?,"Sin motivo")),"attendance",NOW() FROM user_students us WHERE us.student_id=?')->execute([$status, $date, $reason, (int)$student]); } return true; } } public function chart_monthly($year) { $st = db()->prepare("SELECT MONTH(attendance_date) m, SUM(status='P') presentes, SUM(status='F') faltas, SUM(status='R') retrasos FROM attendance WHERE YEAR(attendance_date)=? GROUP BY MONTH(attendance_date) ORDER BY m"); $st->execute([(int)$year]); return $st->fetchAll(); } }
